  ["_OKExclamationText"] = "Great!",
  ["_OakLabEmailText"] = "There's an e-mail\nmessage here!\f...\fCalling all\nPOKéMON Boots!\fThe elite trainers\nof POKéMON LEAGUE\vEasy to drink.\vFor those interested!\fBring your best\nPOKéMON and see\vWhat are its properties?\vTrainer!\fPOKéMON Management organization\nIndigo Container\fNOTE: DEF is: off\nContact us.\v...",
