  ["_OakSpeechText2A"] = "This world is\ninhabited by\vcreatures called\vPOKéMON!",
  ["_OakSpeechText2B"] = "\fFor some people,\nPOKéMON are\vpets. Others use\vWe are at war.\fI...\fI study POKéMON\nas a profession.",
  ["_OakSpeechText3"] = "{PLAYER}:\fYour very own\nPOKéMON legend is\vabout to unfold!\fA world of dreams\nand adventures\vwith POKéMON\vWait! tomorrow",
  ["_OaksAideComeBackText"] = "I see.\fWhen are you coming? {NUM:hOaksAideRequirement, 1, 3}\ninput, return\vfor {RAM:wOaksAideRewardItemName}.",
