  ["_OaksAideHereYouGoText"] = "Great! yes\nFixed {NUM:hOaksAideNumMonsOwned, 1, 3} kinds \vof POKéMON!\vCongratulations!\fCome on!",
  ["_OaksAideHiText"] = "Hello! I'm lonely without you\nI'm PROF.OAK's\vPlease!\fIf you caught {NUM:hOaksAideRequirement, 1, 3}\nkinds of POKéMON,\vYes.\vgive you an\v{RAM:wOaksAideRewardItemName}:\fSo, {PLAYER}! yes\nFixed\vleast {NUM:hOaksAideRequirement, 1, 3} kinds of\vPOKéMON?",
  ["_OaksAideNoRoomText"] = "Right? looking at you\ndon't have any\vroom for the\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Let's see...\nYou! yes,\vcaught only {NUM:hOaksAideNumMonsOwned, 1, 3}\vkinds of POKéMON!\fYou need {NUM:hOaksAideRequirement, 1, 3} kinds\nif you want the\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "PROF.OAK is the\nauthority on\vPOKéMON!\fMany POKéMON\ntrainers hold him\vHello!",
  ["_OaksLabGivePokeballsExplanationText"] = "\fWhen a wild\nPOKéMON appears,\vit's fair game.\fJust like I showed\nyou, throw a POKe\vBALL at it and try\vIf you want it, buy it!\fThis won't always\nwork, though.\fA healthy POKéMON\nI can live with you.\vGood luck!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Come see me\nsometimes.\fI want to know what to do.\nyour POKeDEX is\vcoming along.",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: Oh, {PLAYER}!\fWhat's going on? how are you\nPOKéMON?\fSupposedly.\nI love you very much.\fYou must be\ntalented as a\vPOKéMON Trainer!\fWhat? You have\nsomething for me?\f{PLAYER} delivered\nOAK's PARCEL.",
