  ["_OaksLabOak1ParcelThanksText"] = "\fAh! This is the\nMonster bullet fix\vI've heard of it!\vThanks! {PLAYER}!\fBy the way, I must\nask you to do\vsomething for me.",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "POKéMON around the\nworld wait for\vyou, {PLAYER}!",
